import React from 'react';

import EquipOptionsWidget from '@apps/Hiking/equip/HikingEquip/components/EquipOptionsWidget';
import { err } from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

import { getBackpacks } from '../../../../@services/equip.service';
import { IBackpack } from '../../../../@types/equip.types';
interface IBackpackSelectModalProps {
  onSelect: (bp: IBackpack) => void;
  onCancel?: () => void;
}

const BackpackSelectModal: React.FC<IBackpackSelectModalProps> = ({ onSelect }) => {
  const [backpacks, setBackpacks] = React.useState<IBackpack[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);

  React.useEffect(() => {
    getBackpacks()
      .then(setBackpacks)
      .catch(err)
      .finally(() => setIsLoading(false));
  }, []);

  if (isLoading) {
    return <PohLoader />;
  }

  return (
    <div>
      <PohList
        className="mt-n3"
        data={backpacks.map((backpack) => ({
          action: true,
          onClick: () => onSelect(backpack),
          key: backpack.id,
          content: (
            <div className="d-flex justify-content-between">
              <div className="d-flex align-items-center">
                <PohAva className="my-n3 ms-n2 me-2" alt={backpack.name} src={backpack.photo} />
                {backpack.name}
              </div>
              <EquipOptionsWidget
                value={+backpack.value}
                weight={+backpack.weight}
                className="my-n1 me-2"
              />
            </div>
          ),
        }))}
      />
    </div>
  );
};

export default BackpackSelectModal;
