import React, { useContext } from 'react';

import PatchCheckFill from '@pohodnik/icons/svg/Badges/PatchCheckFill';
import ExclamationDiamond from '@pohodnik/icons/svg/Signs/ExclamationDiamond';
import Chart from 'react-google-charts';
import { Link } from 'react-router-dom';

import { getHikingMenuWeightSummary } from '@apps/Hiking/menu/components/HikingMenu/components/SummaryPanel/hikingMenuSummary.helper';
import PageLoader from '@components/PageLoader';
import { round } from '@helpers/mathHelper';
import { err } from '@helpers/notificationHelper';
import PohList from '@ui-kit/List';

import { AuthContext } from '../../../../../../contexts/AuthContext';
import { includeActInfo } from '../../../../@mappers/hikingMenu.mapper';
import { getHikingDataAsync } from '../../../../@services/hiking.service';
import {
  getFoodAsync,
  getHikingMenuActs,
  getHikingMenuProductsAsync,
} from '../../../../@services/hikingMenu.service';
import { getHikingMenuSavesAsync } from '../../../../@services/hikingMenuSaves.service';
import { IHikingMenuSave } from '../../../../@types/hiking.baseTypes';
import { IHikingData } from '../../../../@types/hiking.types';
import {
  IHikingMenuExtendedProduct,
  IHikingMenuFoodWithAct,
} from '../../../../@types/hikingMenu.types';
interface IEquipFoodProps {
  id_hiking: number;
  id_user: number | null;
  onReady: (weight: number) => void;
}

const EquipFood: React.FC<IEquipFoodProps> = ({ id_hiking, onReady, id_user }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [food, setFood] = React.useState<IHikingMenuFoodWithAct[]>([]);
  const [products, setProducts] = React.useState<IHikingMenuExtendedProduct[]>([]);
  const [saves, setSaves] = React.useState<IHikingMenuSave[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [max, setMax] = React.useState<number>(0);
  const [dateWeight, setDateWeight] = React.useState<Record<string, number>>({});

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        await getHikingDataAsync(id_hiking).then(setHikingData);
        const hda = await getHikingMenuActs(id_hiking);

        const hf = await getFoodAsync({ id_hiking });
        const hfWithActs = hf.map(includeActInfo(hda));
        setFood(hfWithActs);

        await getHikingMenuProductsAsync(id_hiking).then(setProducts);
        await getHikingMenuSavesAsync(id_hiking).then(setSaves);
      } finally {
        setIsLoading(false);
      }
    };

    init().catch(err);
  }, [id_hiking]);

  React.useEffect(() => {
    if (isLoading || !authContext.user) return;
    const { dateUserWeightAggregation, maxUserLoads } = getHikingMenuWeightSummary(
      food,
      products,
      hikingData?.hikers.length ?? 1,
    );

    const user = id_user ?? +authContext.user.id;

    let startLoad = maxUserLoads[user] ?? 0;
    const dateWeightMap: Record<string, number> = {};

    Object.keys(dateUserWeightAggregation)
      .sort()
      .forEach((dateStr) => {
        dateWeightMap[dateStr] = startLoad;
        startLoad -=
          (dateUserWeightAggregation[dateStr]?.[user] || 0) * (hikingData?.hikers.length ?? 1);
      });

    setDateWeight(dateWeightMap);
    setMax(maxUserLoads[user] ?? 0);

    onReady(maxUserLoads[user] ?? 0);
  }, [isLoading, food, products, hikingData]);

  if (isLoading) {
    return <PageLoader />;
  }

  const confirmedSave = saves.find((s) => s.confirmDate);

  return (
    <div>
      {confirmedSave ? (
        <div className="d-flex align-items-center mb-2">
          <PatchCheckFill className="text-success" /> &nbsp;{' '}
          <small
            title={[confirmedSave.confirmDate?.toLocaleString(), confirmedSave.confirmUser].join(
              '\n',
            )}
          >
            <Link to={`/hiking/${id_hiking}/menu`}>Меню</Link> утверждено{' '}
            {confirmedSave.confirmDate?.toLocaleDateString()}
          </small>
        </div>
      ) : (
        <div className="d-flex align-items-center mb-2 bg-warning px-3">
          <ExclamationDiamond className="warning" />
          &nbsp;{' '}
          <small>
            <Link to={`/hiking/${id_hiking}/menu`}>Меню</Link> не утверждено и может поменяться
          </small>
        </div>
      )}
      <PohList
        data={[
          {
            key: '1',
            content: (
              <span
                title={Object.entries(dateWeight)
                  .map(([dateStr, weight]) => {
                    return [
                      new Date(dateStr).toLocaleDateString(),
                      round(weight / 1000, 2),
                      'кг.',
                    ].join('\t');
                  })
                  .join('\n')}
              >
                На старте: <strong>{round(max / 1000, 2)}</strong>&thinsp;кг.
              </span>
            ),
          },
        ]}
      />

      {Object.keys(dateWeight).length > 0 && (
        <Chart
          chartLanguage="ru"
          chartType="LineChart"
          loader={<PageLoader />}
          data={[
            ['Дата', 'Вес провизии'],
            ...Object.entries(dateWeight).map(([dateStr, weight]) => {
              return [new Date(dateStr), round(weight / 1000, 2)];
            }),
          ]}
          options={{
            title: 'Убывание веса провизии',
            height: 240,
            chartArea: { width: '100%' },
            intervals: { style: 'sticks' },
            legend: 'none',
            color: 'red',
            // legend: { position: 'bottom', alignment: 'end' },
            // crosshair: {
            //     color: 'lime',
            //     trigger: 'selection'
            // },
            // smoothLine: true,
            // hAxis: { format: 'd.MM\u2008HH', gridlines: { count: 3 } },
            // vAxis: {                          format: 'short',
            //     viewWindowMode: 'explicit',
            //     gridlines: { count: 6 },
            //     viewWindow: {
            //         min: 0
            //     }
            // },
            //
            // //series
          }}
        />
      )}
    </div>
  );
};

export default EquipFood;
