import React from 'react';

import BagCheckFill from '@pohodnik/icons/svg/Commerce/BagCheckFill';
import clsx from 'clsx';

import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton from '@ui-kit/Button';
import PohDropdown from '@ui-kit/Dropdown';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputSizes, InputTypes } from '@ui-kit/Input';

import { ISetEquip } from '../../../../@types/equip.types';
import { previewEquipModal } from '../../previewEquip/previewEduipModal';
import EquipOptionsWidget from '../EquipOptionsWidget';

interface IEquipItemProps {
  owner: ISetEquip['owner'] | null;
  photo: string;
  name: string;
  weight: number;
  value: number;
  amount?: number;
  is_musthave?: boolean;
  is_active?: boolean;
  is_group?: boolean;
  onEdit: () => void;
  onDelete: () => void;
  onChangeAmount?: (newAmount: number) => void;
  onToggleOnMe?: () => void;
  onCheck?: () => void;
  onAssign: () => void;
  is_archive?: boolean;

  is_on_me?: boolean;
  readonly?: boolean;
}

const EquipItem: React.FC<IEquipItemProps> = ({
  photo,
  name,
  is_musthave = false,
  weight,
  value,
  onEdit,
  onDelete,
  onAssign,
  is_group = false,
  is_archive = false,
  readonly = false,
  owner = null,
  amount,
  onChangeAmount,
  is_active,
  onToggleOnMe,
  onCheck,
  is_on_me,
}) => {
  const menu = [];

  onToggleOnMe &&
    menu.push(
      <button key="assign-equip" className="dropdown-item" onClick={onToggleOnMe} type="button">
        {is_on_me ? 'Будет в рюкзаке' : 'Будет на мне'}
      </button>,
    );
  onCheck &&
    menu.push(
      <button key="assign-equip" className="dropdown-item" onClick={onCheck} type="button">
        {is_active ? 'Не взял(a)' : 'Взял(a)'}
      </button>,
    );

  onCheck || (onToggleOnMe && menu.push(<div key="div" className="dropdown-divider" />));

  !owner &&
    menu.push(
      <button key="edit-equip" className="dropdown-item" onClick={onEdit} type="button">
        Редактировать
      </button>,
    );

  menu.push(
    <button key="assign-equip" className="dropdown-item" onClick={onAssign} type="button">
      Назначить кому-то{is_group ? '!' : ''}
    </button>,
  );

  menu.push(<div key="div" className="dropdown-divider" />);
  menu.push(
    <button key="del-equip" className="dropdown-item" onClick={onDelete} type="button">
      Удалить из сборки
    </button>,
  );

  return (
    <div
      className="d-flex justify-content-between align-items-center my-n1"
      style={{ userSelect: 'none' }}
    >
      <div className="d-flex flex-nowrap align-items-center ms-n2 flex-grow-1">
        {is_active && (
          <BagCheckFill
            className="mx-2 text-success"
            style={{ position: 'absolute', top: '4px', left: '0' }}
          />
        )}
        {owner && (
          <PohAva
            width={16}
            style={{ position: 'absolute', bottom: '6px', left: '32px' }}
            src={owner.photo}
            alt={owner.name}
            title={`Владелец: ${owner.name}`}
          />
        )}
        <PohAva
          src={photo}
          alt={name}
          className="me-2"
          style={{
            opacity: is_archive ? 0.5 : 1,
          }}
          onClick={() => previewEquipModal({ photo, value, weight, name })}
        />
        <span className={clsx({ 'text-muted': is_archive, 'font-weight-bold': is_musthave })}>
          {name}
        </span>
        {/*{is_musthave && (*/}
        {/*    <PohBadge rounded variant={BadgeVariant.Warning} className="ms-2">*/}
        {/*        Мастхэв*/}
        {/*    </PohBadge>*/}
        {/*)}*/}
        {is_archive && (
          <PohBadge rounded variant={BadgeVariant.Danger} className="ms-2">
            Archive
          </PohBadge>
        )}

        {is_on_me && (
          <PohBadge
            rounded
            variant={BadgeVariant.Success}
            className="ms-2"
            title="Нет смысла учитывать в весе рюкзака, так как будет на мне"
          >
            На мне
          </PohBadge>
        )}
      </div>
      <aside className="d-flex flex-nowrap align-items-center">
        {onChangeAmount && (
          <span className="d-flex align-items-center" title="Количество">
            <PohDropdown
              menu={
                <div className="py-n2 px-2">
                  <small>Указать количество</small>
                  <PohInput
                    type={InputTypes.number}
                    value={(amount ?? 1).toString()}
                    min={1}
                    maxLength={2}
                    size={InputSizes.Small}
                    onChange={(v) => onChangeAmount?.(+v || 1)}
                    disabled={readonly}
                  />
                </div>
              }
            >
              {amount && amount > 1 ? (
                <strong className="text-danger text-strong">
                  {amount}&thinsp;<small>шт.</small>
                </strong>
              ) : (
                <span className="text-muted">{amount}</span>
              )}
            </PohDropdown>
            <small className="text-muted">&nbsp;×&nbsp;</small>
          </span>
        )}
        <EquipOptionsWidget weight={round(weight / 1000)} value={round(value)} />
        {!readonly && (
          <PohDropdown className="me-n2" menu={menu}>
            <PohButton icon={IconsEnum.right_menu} />
          </PohDropdown>
        )}
      </aside>
    </div>
  );
};

export default EquipItem;
